  const iv=setInterval(()=>{if(stop)return;t+=.02/api.ez;for(let i=0;i<2;i++){pos[i]=50+Math.sin(t*sp[i]*2.2+i*1.7)*46;N[i].style.left=`calc(${pos[i]}% - 6px)`}},20);
