MG.xlSeal={n:'ผนึกชิ้นส่วนที่ตื่น',ic:'📿',mt:'ผู้คุมเสียงในหัว',how:'แตะยันต์ตามลำดับ 1→8 ก่อนเวลาหมด ยันต์จะสลับที่ทุกสามวินาที',t:22,rw:()=>'',
 init(B2,api){let nx=1,miss=0,stop=0;B2.innerHTML=`<div class="tag2" id="xeH" style="text-align:center"></div>${box(300)}<div id="xeF" style="position:absolute;inset:0"></div></div>`;
  const F=B2.querySelector('#xeF'),H=B2.querySelector('#xeH');const upd=()=>{H.textContent=`${L('ถัดไป','Next')}: ${nx<=8?nx:'✓'} · ${L('พลาด','Misses')} ${miss}`};
  const lay=()=>{F.innerHTML='';const used=[];for(let i=1;i<=8;i++){if(i<nx)continue;let x,y,g=0;do{x=Ri(4,78);y=Ri(4,80);g++}while(g<40&&used.some(u=>Math.abs(u[0]-x)<16&&Math.abs(u[1]-y)<14));used.push([x,y]);const b=document.createElement('button');b.textContent=i;b.style.cssText=`position:absolute;left:${x}%;top:${y}%;width:44px;height:44px;border-radius:10px;border:2px solid #e0b04a;background:#3a2a10;color:#ffe08a;font-weight:900;font-size:18px`;b.onpointerdown=e=>{e.preventDefault();if(!api.live())return;if(i===nx){nx++;b.remove();vib(20);if(nx>8)api.end()}else{miss++;vib(120)}upd()};F.appendChild(b)}upd()};lay();
  const iv=setInterval(()=>{if(!stop&&api.live())lay()},Math.round(3000*api.ez));
  return{sc:()=>cl((nx-1)/8-miss*.08,0,1),stop(){stop=1;clearInterval(iv)}}}};
