  const Fi=[...B2.querySelectorAll('[data-f]')],H=B2.querySelector('#xvH');B2.querySelectorAll('[data-v]').forEach(b=>b.onpointerdown=e=>{e.preventDefault();if(!api.live())return;const i=+b.dataset.v;v[i]=Math.max(0,v[i]-14);vib(12)});
