MG.xlEdit={n:'ตัดต่อคลิปไวรัล',ic:'🎬',mt:'มือตัดต่อพันล้านวิว',how:'ไทม์ไลน์เลื่อนผ่านเส้นแดง แตะตอนช่วงไฮไลต์ ✨ อยู่ตรงเส้น ช่วงน่าเบื่อ 😴 ห้ามแตะ',t:24,rw:()=>'',
 init(B2,api){let hit=0,bad=0,stop=0,x=0;const seg=[];let at=60;for(let i=0;i<40;i++){const h=rnd()<.4;seg.push({x:at,w:h?Ri(26,40):Ri(30,60),h,u:0});at+=seg[seg.length-1].w+Ri(6,18)}
  B2.innerHTML=`<div class="tag2" id="xdH" style="text-align:center"></div>${box(110)}<div id="xdT" style="position:absolute;top:30px;height:50px;left:0"></div><div style="position:absolute;left:50%;top:10px;bottom:10px;width:3px;background:#ff3a4a;box-shadow:0 0 10px #ff3a4a"></div></div><button class="pbtn" id="xdB" style="width:100%;margin-top:10px;padding:16px;font-size:18px">✂️ ${L('ตัด!','Cut!')}</button>`;
  const T=B2.querySelector('#xdT'),H=B2.querySelector('#xdH');T.innerHTML=seg.map((s,i)=>`<div data-s="${i}" style="position:absolute;left:${s.x}px;width:${s.w}px;top:0;bottom:0;border-radius:6px;background:${s.h?'#ffcf4d':'#4a4a6a'};display:flex;align-items:center;justify-content:center;font-size:18px">${s.h?'✨':'😴'}</div>`).join('');
  const upd=()=>{H.textContent=`✨ ${hit} · 😴 ${bad}/3`};upd();const W0=()=>(T.parentNode.clientWidth||300)/2;
  B2.querySelector('#xdB').onclick=()=>{if(!api.live())return;const px=W0()+x;const s=seg.find(z=>px>=z.x&&px<=z.x+z.w);if(s&&s.h&&!s.u){s.u=1;hit++;vib(25);T.querySelector(`[data-s="${seg.indexOf(s)}"]`).style.background='#2ad07a'}else if(s&&!s.h){bad++;vib(140);if(bad>=3)api.end()}upd();if(hit>=10)api.end()};
  const iv=setInterval(()=>{if(stop)return;x+=1.7/api.ez;T.style.transform=`translateX(${-x}px)`;if(W0()+x>at)api.end()},20);
  return{sc:()=>cl(hit/10-bad*.15,0,1),stop(){stop=1;clearInterval(iv)}}}};
// 8) สั่งคลาสยิม — คำสั่งขึ้นมา ทำตาม แต่ถ้าโค้ชพูดว่า "กลับ!" ต้องกดทิศตรงข้าม
const DIR=['⬆️','➡️','⬇️','⬅️'];
MG.xlCoach={n:'คลาสกำลังภายใน',ic:'🥋',mt:'โค้ชเสียงทรงพลัง',how:'กดทิศตามคำสั่ง แต่ถ้ามีคำว่า "กลับ!" 🔄 ต้องกดทิศตรงข้าม · มีเวลาน้อยลงเรื่อยๆ',t:26,rw:()=>'',
 init(B2,api){let ok=0,n=0,stop=0,cur=null,tm=null;B2.innerHTML=`<div class="tag2" id="xcH" style="text-align:center"></div><div id="xcC" style="margin:12px 0;height:90px;display:flex;align-items:center;justify-content:center;font-size:54px;border-radius:14px;background:#141022;border:1px solid #4a3a6a"></div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">${DIR.map((d,i)=>`<button class="opt" data-d="${i}" style="font-size:30px;padding:14px 0">${d}</button>`).join('')}</div>`;
  const C=B2.querySelector('#xcC'),H=B2.querySelector('#xcH');const upd=()=>{H.textContent=`${L('ถูก','Correct')} ${ok}/${n}`};
  const nx=()=>{if(stop||!api.live())return;if(n>=14){api.end();return}const d=Ri(0,3),rv=rnd()<.35;cur={d,rv,want:rv?(d+2)%4:d};C.innerHTML=`${DIR[d]}${rv?`<span style="font-size:26px;color:#ff6a8a;margin-left:8px">🔄 ${L('กลับ!','Reverse!')}</span>`:''}`;clearTimeout(tm);tm=setTimeout(()=>{n++;vib(80);upd();nx()},Math.max(650,Math.round((1900-n*80)*api.ez)))};
  B2.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{if(!cur||!api.live())return;clearTimeout(tm);n++;if(+b.dataset.d===cur.want){ok++;vib(15)}else vib(120);upd();nx()});upd();setTimeout(nx,400);
  return{sc:()=>ok/14,stop(){stop=1;clearTimeout(tm)}}}};
// 9) สาดน้ำสงกรานต์ — แตะคนเล่นน้ำ 😆 · ผู้ใหญ่ 🙏 ต้องกดค้างเพื่อรดน้ำดำหัวเบาๆ ห้ามสาด
MG.xlSplash={n:'สาดน้ำข้ามภพ',ic:'💦',mt:'เจ้าแห่งขันเงิน',how:'แตะคนที่เล่นน้ำ 😆 เพื่อสาด · ผู้ใหญ่ 🙏 ให้กดค้างเพื่อรดน้ำดำหัวอย่างนอบน้อม ห้ามแตะสาดใส่',t:22,rw:()=>'',
 init(B2,api){let sc=0,rude=0,stop=0;const ps=[];B2.innerHTML=`<div class="tag2" id="xsP" style="text-align:center"></div>${box(300)}<div id="xsF" style="position:absolute;inset:0;background:linear-gradient(#5ad0ff22,#1a6aff22)"></div></div>`;
  const F=B2.querySelector('#xsF'),H=B2.querySelector('#xsP');const upd=()=>{H.textContent=`💦 ${sc} · 😳 ${L('เสียมารยาท','Rude')} ${rude}/3`};upd();
  const iv=setInterval(()=>{if(stop)return;if(rnd()<.045/Math.sqrt(api.ez)&&ps.filter(p=>!p.dead).length<6){const el=rnd()<.3,e=document.createElement('div');e.textContent=el?'🙏':pick(['😆','🤣','😎','🥳']);e.style.cssText=`position:absolute;font-size:38px;left:${Ri(4,82)}%;top:${Ri(4,78)}%;transition:transform .2s;cursor:pointer`;const o={e,el,t:0,life:Ri(70,120),hold:0,ht:null};
    e.onpointerdown=ev=>{ev.preventDefault();if(!api.live()||o.dead)return;if(!el){o.dead=1;e.textContent='💦';vib(15);sc++;upd();setTimeout(()=>e.remove(),250)}else{o.hold=1;e.style.transform='scale(1.2)';o.ht=setTimeout(()=>{if(o.hold&&!o.dead){o.dead=1;e.textContent='🌼';sc+=2;vib(30);upd();setTimeout(()=>e.remove(),350)}},Math.round(650*api.ez))}};
    const up=()=>{if(o.el&&o.hold&&!o.dead){clearTimeout(o.ht);o.hold=0;o.dead=1;e.textContent='😠';rude++;vib(160);upd();setTimeout(()=>e.remove(),350);if(rude>=3)api.end()}};e.onpointerup=up;e.onpointerleave=up;F.appendChild(e);ps.push(o)}
   ps.forEach(o=>{if(o.dead)return;o.t++;if(o.t>o.life){o.dead=1;o.e.remove()}})},30);
  return{sc:()=>cl(sc/18-rude*.2,0,1),stop(){stop=1;clearInterval(iv)}}}};
// 10) รับอั่งเปา — ลากถุงรับซองแดง หลบประทัด
MG.xlAngpao={n:'รับอั่งเปาตรุษจีน',ic:'🧧',mt:'มือรับทรัพย์',how:'ลากนิ้วซ้ายขวาเพื่อเลื่อนถุงรับซองแดง 🧧 หลบประทัด 🧨 ส้ม 🍊 ได้สองแต้ม',t:22,rw:()=>'',
 init(B2,api){let sc=0,boom=0,stop=0,bx=50;const it=[];B2.innerHTML=`<div class="tag2" id="xaH" style="text-align:center"></div>${box(300)}<div id="xaF" style="position:absolute;inset:0;background:radial-gradient(#7a1a1a,#2a0808)"></div><div id="xaB" style="position:absolute;bottom:6px;font-size:40px;margin-left:-22px">👜</div></div>`;
  const F=B2.querySelector('#xaF'),Bg=B2.querySelector('#xaB'),A=Bg.parentNode,H=B2.querySelector('#xaH');const upd=()=>{H.textContent=`🧧 ${sc} · 🧨 ${boom}/3`};upd();
  const mv=e=>{const r=A.getBoundingClientRect();bx=cl((e.clientX-r.left)/r.width*100,6,94)};A.onpointerdown=e=>{e.preventDefault();mv(e)};A.onpointermove=e=>{if(e.buttons||e.pointerType==='touch')mv(e)};
  const iv=setInterval(()=>{if(stop)return;Bg.style.left=bx+'%';if(rnd()<.05/Math.sqrt(api.ez)){const k=rnd(),t=k<.25?'🧨':k<.4?'🍊':'🧧',e=document.createElement('div');e.textContent=t;e.style.cssText=`position:absolute;font-size:30px;margin-left:-15px;left:${Ri(6,94)}%;top:-30px`;F.appendChild(e);it.push({e,t,x:parseFloat(e.style.left),y:-30,v:1.4+rnd()*1.6+sc*.03})}
   it.forEach(o=>{if(o.dead)return;o.y+=o.v/api.ez;o.e.style.top=o.y+'px';if(o.y>238&&o.y<275&&Math.abs(o.x-bx)<11){o.dead=1;o.e.remove();if(o.t==='🧨'){boom++;vib(160);if(boom>=3)api.end()}else{sc+=o.t==='🍊'?2:1;vib(12)}upd()}else if(o.y>300){o.dead=1;o.e.remove()}})},20);
  return{sc:()=>cl(sc/20-boom*.15,0,1),stop(){stop=1;clearInterval(iv)}}}};
// 11) หลบสายฟ้าทัณฑ์ — ช่อง 3×3 ช่องที่ขึ้นเตือนจะโดนฟ้าผ่า แตะย้ายไปช่องปลอดภัยก่อนผ่า
MG.xlBolt={n:'ซ้อมรับทัณฑ์สวรรค์',ic:'⚡',mt:'ผู้หัวเราะใส่สายฟ้า',how:'ช่องที่กะพริบเหลืองกำลังจะโดนฟ้าผ่า แตะช่องที่ปลอดภัยเพื่อย้ายตัวไปก่อนฟ้าลง · รอด 10 ระลอก',t:30,rw:()=>'',
 init(B2,api){let me=4,wave=0,hit=0,stop=0,warn=[],tm=null;B2.innerHTML=`<div class="tag2" id="xbH" style="text-align:center"></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:8px">${[...Array(9)].map((_,i)=>`<button data-g="${i}" style="height:84px;border-radius:12px;border:2px solid #4a4a8a;background:#141433;font-size:34px"></button>`).join('')}</div>`;
  const G=[...B2.querySelectorAll('[data-g]')],H=B2.querySelector('#xbH');const drw=()=>{G.forEach((g,i)=>{g.textContent=i===me?'🧘':'';g.style.background=warn.includes(i)?'#5a4a10':'#141433';g.style.borderColor=warn.includes(i)?'#ffd34a':'#4a4a8a'});H.textContent=`⚡ ${L('ระลอก','Wave')} ${wave}/10 · ${L('โดนผ่า','Struck')} ${hit}/3`};
  G.forEach((g,i)=>g.onclick=()=>{if(api.live()){me=i;drw()}});
  const go=()=>{if(stop||!api.live())return;if(wave>=10){api.end();return}const n=Math.min(7,3+Math.floor(wave/2));warn=shuf([0,1,2,3,4,5,6,7,8]).slice(0,n);if(!warn.includes(me)&&rnd()<.7)warn[0]=me;drw();
   tm=setTimeout(()=>{if(stop)return;G.forEach((g,i)=>{if(warn.includes(i)){g.textContent='⚡';g.style.background='#fff7a0'}});if(warn.includes(me)){hit++;vib(200)}wave++;warn=[];setTimeout(()=>{drw();if(hit>=3)api.end();else go()},380)},Math.max(700,Math.round((1500-wave*60)*api.ez)))};drw();setTimeout(go,500);
  return{sc:()=>cl(1-hit/3,0,1)*cl(wave/10,0,1),stop(){stop=1;clearTimeout(tm)}}}};
// 12) คุยกับศัตรูเก่า — 4 รอบ เลือกคำพูดหนึ่งในสาม ดูสีหน้าเขาแล้วเดาว่าอะไรจะเข้าถึงใจ
const TALK=[[['ข้าขอโทษ','I am sorry'],['เจ้าสมควรตาย','You deserved it'],['ข้าจำไม่ได้','I don\'t remember']],[['เราเกิดใหม่แล้ว จบกันเถอะ','We were reborn. Let it end'],['สู้กันอีกรอบสิ','Fight me again'],['เจ้าต้องการอะไร','What do you want?']],[['ข้าเองก็เคยเสียคนสำคัญ','I lost someone too'],['ความแค้นทำให้เจ้าแข็งแกร่งงั้นรึ','Does hatred make you strong?'],['ไปให้พ้น','Get lost']],[['ข้าจะชดใช้ในชาตินี้','I will repay you in this life'],['ข้าไม่เสียใจ','I regret nothing'],['เราเหมือนกันนะ','We\'re the same, you and I']]];
MG.xlTalk={n:'คุยกับศัตรูข้ามชาติ',ic:'🗣️',mt:'ผู้ปลดปมข้ามชาติ',how:'4 รอบ เลือกคำพูดที่จะเข้าถึงใจศัตรู ดูสีหน้าเขาเป็นคำใบ้ (คำตอบที่ถูกเปลี่ยนไปตามนิสัยเขา)',t:40,rw:()=>'',
 init(B2,api){const per=Ri(0,2);let rd=0,heart=0,stop=0;const want=[[0,2,0,0],[0,2,1,2],[2,0,1,0]][per];const face=['😠','😤','😐','🥲','😢'];
  const nx=()=>{if(stop)return;if(rd>=4){api.end();return}const T=TALK[rd],ix=shuf([0,1,2]);const mood=cl(2+heart-Math.floor(rd/2),0,4);
   B2.innerHTML=`<div class="tag2" style="text-align:center">${L('รอบ','Round')} ${rd+1}/4 · ${L('หัวใจ','Heart')} ${'💗'.repeat(Math.max(0,heart))}</div><div style="text-align:center;font-size:64px;margin:6px 0">${face[mood]}</div><p class="tag2" style="text-align:center">${L(['เขาจ้องคุณไม่วางตา','กำปั้นเขาสั่น','เขาเงียบไปนาน','ตาเขาแดงก่ำ'][rd],['He stares at you unblinking','His fists tremble','He is silent a long time','His eyes are red'][rd])}${per===1?L(' · ดูเหมือนเขาอยากได้ยินคำท้า',' · he seems to want a challenge'):per===2?L(' · เขาดูอยากรู้ความจริงมากกว่าคำขอโทษ',' · he wants truth more than apology'):''}</p>${ix.map(i=>`<button class="opt" data-i="${i}" style="width:100%;margin-top:6px;text-align:left">💬 ${L(T[i][0],T[i][1])}</button>`).join('')}`;
   B2.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{if(!api.live())return;const i=+b.dataset.i;if(i===want[rd]){heart++;vib(25)}else if(rd>0&&T[i]===T[(want[rd]+1)%3]){heart-=0}else{heart--;vib(100)}rd++;setTimeout(nx,250)})};nx();
  return{sc:()=>cl((heart+1)/5,0,1),stop(){stop=1}}}};
// 13) ตามรอยเงาชาติก่อน — รอยเท้าโผล่ทีละช่องบนตาราง 4×4 จำแล้วแตะตามเส้นทาง
MG.xlTrack={n:'ตามรอยสัตว์วิญญาณ',ic:'🐾',mt:'นักล่าเงาตัวเอง',how:'รอยเท้าจะโผล่ทีละช่อง จำเส้นทางไว้ แล้วแตะตามลำดับ · ยาวขึ้นทีละรอบ',t:36,rw:()=>'',
 init(B2,api){let len=4,best=0,stop=0;const tms=[];
  const run=()=>{if(stop)return;const path=[Ri(0,15)];while(path.length<len){const p=path[path.length-1],r=Math.floor(p/4),c=p%4,nb=[[r-1,c],[r+1,c],[r,c-1],[r,c+1]].filter(([a,b])=>a>=0&&a<4&&b>=0&&b<4).map(([a,b])=>a*4+b).filter(q=>!path.includes(q));if(!nb.length)break;path.push(pick(nb))}
   B2.innerHTML=`<div class="tag2" id="xtH" style="text-align:center">${L('จำรอยเท้า…','Memorize the tracks…')} (${path.length})</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:8px">${[...Array(16)].map((_,i)=>`<button data-t="${i}" style="height:64px;border-radius:10px;border:2px solid #3a5a3a;background:#14221a;font-size:28px"></button>`).join('')}</div>`;
   const C=[...B2.querySelectorAll('[data-t]')],H=B2.querySelector('#xtH');let k=0,inp=0,ph=0;const sh=()=>{if(stop)return;if(k>=path.length){C.forEach(c=>c.textContent='');ph=1;H.textContent=L('ตามรอยเลย!','Follow the trail!');return}C[path[k]].textContent='🐾';k++;tms.push(setTimeout(sh,Math.round(520*api.ez)))};tms.push(setTimeout(sh,500));
   C.forEach((c,i)=>c.onclick=()=>{if(!ph||!api.live())return;if(i!==path[inp]){c.style.background='#5a1a1a';ph=0;tms.push(setTimeout(()=>api.end(),450));return}c.textContent='🐾';c.style.background='#2a5a2a';inp++;if(inp>=path.length){best=path.length;ph=0;if(len>=9){tms.push(setTimeout(()=>api.end(),300));return}len++;tms.push(setTimeout(run,550))}})};run();
  return{sc:()=>cl((best-3)/6,0,1),stop(){stop=1;tms.forEach(clearTimeout)}}}};
